                $useMinMax = true;
            }
            if (isset($destinoId['max'])) {
                $this->addUsingAlias(FactHistVitacoraPeer::DESTINO_ID, $destinoId['max'], Criteria::LESS_EQUAL);
                $useMinMax = true;
            }
            if ($useMinMax) {
                return $this;
            }
            if (null === $comparison) {
                $comparison = Criteria::IN;
            }
        }

        return $this->addUsingAlias(FactHistVitacoraPeer::DESTINO_ID, $destinoId, $comparison);
    }

    /**
     * Filter the query on the OBSERVACIONES column
     *
     * Example usage:
     * <code>
     * $query->filterByObservaciones('fooValue');   // WHERE OBSERVACIONES = 'fooValue'
     * $query->filterByObservaciones('%fooValue%'); // WHERE OBSERVACIONES LIKE '%fooValue%'
     * </code>
     *
     * @param     string $observaciones The value to use as filter.
     *              Accepts wildcards (* and % trigger a LIKE)
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return FactHistVitacoraQuery The current query, for fluid interface
     */
    public function filterByObservaciones($observaciones = null, $comparison = null)
    {
        if (null === $comparison) {
            if (is_array($observaciones)) {
                $comparison = Criteria::IN;
            } elseif (preg_match('/[\%\*]/', $observaciones)) {
                $observaciones = str_replace('*', '%', $observaciones);
                $comparison = Criteria::LIKE;
            }
        }

        return $this->addUsingAlias(FactHistVitacoraPeer::OBSERVACIONES, $observaciones, $comparison);
    }

    /**
