     * @throws PropelException - if the provided filter is invalid.
     */
    public function filterByFactHist($factHist, $comparison = null)
    {
        if ($factHist instanceof FactHist) {
            return $this
                ->addUsingAlias(FactHistVitacoraPeer::FACTHIST_ID, $factHist->getFacthistId(), $comparison);
        } elseif ($factHist instanceof PropelObjectCollection) {
            if (null === $comparison) {
                $comparison = Criteria::IN;
            }

            return $this
                ->addUsingAlias(FactHistVitacoraPeer::FACTHIST_ID, $factHist->toKeyValue('PrimaryKey', 'FacthistId'), $comparison);
        } else {
            throw new PropelException('filterByFactHist() only accepts arguments of type FactHist or PropelCollection');
        }
    }

    /**
     * Adds a JOIN clause to the query using the FactHist relation
     *
     * @param     string $relationAlias optional alias for the relation
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return FactHistVitacoraQuery The current query, for fluid interface
     */
    public function joinFactHist($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        $tableMap = $this->getTableMap();
        $relationMap = $tableMap->getRelation('FactHist');

        // create a ModelJoin object for this join
        $join = new ModelJoin();
        $join->setJoinType($joinType);
        $join->setRelationMap($relationMap, $this->useAliasInSQL ? $this->getModelAlias() : null, $relationAlias);
        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'FactHist');
        }

        return $this;
    }

    /**
     * Use the FactHist relation FactHist object
     *
     * @see       useQuery()
