     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   FactHistQuery A secondary query class using the current class as primary query
     */
    public function useFactHistQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinFactHist($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'FactHist', 'FactHistQuery');
    }

